python3 - <<'PY'
from pathlib import Path
import re
for root in ['app/views','app/controllers','app/helpers','app/models','app/mailers','app/javascript']:
    files=list(Path(root).rglob('*'))
    files=[f for f in files if f.is_file() and f.suffix in ('.erb','.rb','.js')]
    pats=[re.compile(p) for p in [r'"[A-Za-z][^"\n]{2,}"',r"'[A-Za-z][^'\n]{2,}'"]]
    found=[]
    for f in files:
        for i,line in enumerate(f.read_text(errors='ignore').splitlines(),1):
            if any(p.search(line) for p in pats): found.append((str(f),i,line.strip()))
    print(root, len(found))
PY

