from pathlib import Path
import re
for f in Path('app/views').rglob('*.erb'):
 if f.suffix=='.erb':
  text=f.read_text(errors='ignore')
  # text chunks outside erb tags, including attrs
  chunks=re.split(r'<%.*?%>', text, flags=re.S)
  # remove html tags/comments
  vals=[]
  for c in chunks:
   c=re.sub(r'<!--.*?-->', '',c,flags=re.S)
   for m in re.finditer(r'>([^<>]+)<',c):
    s=' '.join(m.group(1).split())
    if re.search(r'[A-Za-z]{2}',s): vals.append(s)
  if vals: print(f'{f}: {" | ".join(vals)}')
