    if (!this.#referrerUrl) return null
    return new URL(this.#referrerUrl).pathname
  }

  get #referrerUrl() {
    return sessionStorage.getItem("referrerUrl")
  }

  get #referrerLabel() {
    return sessionStorage.getItem("referrerLabel")
  }
}
