text.sub!("    this.timeordateFormatter = new TimeOrDateFormatter()", "    this.timeordateFormatter = new TimeOrDateFormatter(DEFAULT_LOCALE)")
start=text.index("class AgoFormatter\n")
finish=text.index("function styleableValue", start)
abort "relative formatter block not found" unless start && finish
block=<<'JS'
class AgoFormatter {
  constructor(locale) {
    this.locale = locale
    this.japanese = locale.startsWith("ja")
  }

  format(dt) {
    const now = new Date()
    const seconds = (now - dt) / 1000
    const minutes = seconds / 60
    const hours = minutes / 60
    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (years >= 1) return this.#pluralize("year", years)
    if (months >= 1) return this.#pluralize("month", months)
    if (weeks >= 1) return this.#pluralize("week", weeks)
    if (days >= 1) return this.#pluralize("day", days)
    if (hours >= 1) return this.#pluralize("hour", hours)
    if (minutes >= 1) return this.#pluralize("minute", minutes)

    return this.japanese ? "1分未満前" : "Less than a minute ago"
  }

  #pluralize(word, quantity) {
    quantity = Math.floor(quantity)

    if (this.japanese) {
      const suffix = { year: "年前", month: "か月前", week: "週間前", day: "日前", hour: "時間前", minute: "分前" }[word]
      return `${new Intl.NumberFormat(this.locale).format(quantity)}${suffix}`
    }

    const suffix = (quantity === 1) ? "" : "s"
    return `${quantity} ${word}${suffix} ago`
  }
}

class DaysAgoFormatter {
  constructor(locale) {
    this.locale = locale
    this.japanese = locale.startsWith("ja")
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 0) return styleableValue(this.japanese ? "今日" : "today")
    if (days === 1) return styleableValue(this.japanese ? "昨日" : "yesterday")
    return this.japanese ? `${styleableValue(days)}日前` : `${styleableValue(days)} days ago`
  }
}

class DaysAgoOrWeekdayFormatter {
  constructor(locale) {
    this.locale = locale
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 1) {
      return new DaysAgoFormatter(this.locale).format(date)
    } else {
      return new Intl.DateTimeFormat(this.locale, { weekday: "long", month: "long", day: "numeric" }).format(date)
    }
  }
}

class InDaysFormatter {
  constructor(locale) {
    this.locale = locale
    this.japanese = locale.startsWith("ja")
  }

  format(date) {
    const days = differenceInDays(new Date(), date)

    if (days <= 0) return styleableValue(this.japanese ? "今日" : "today")
    if (days === 1) return styleableValue(this.japanese ? "明日" : "tomorrow")
    return this.japanese ? `あと${styleableValue(days)}日` : `in ${styleableValue(days)} days`
  }
}

class TimeOrDateFormatter {
  constructor(locale) {
    this.locale = locale
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days >= 1) {
      return new Intl.DateTimeFormat(this.locale, { month: "short", day: "numeric" }).format(date)
    } else {
      return new Intl.DateTimeFormat(this.locale, { timeStyle: "short" }).format(date)
    }
  }
}

